def derive_states(apps, schema_editor):
    """ردیف‌هایِ موجود: آمادگیِ فنی/وضعیتِ تجاری را از طبقه‌بندیِ قبلی (availability) مشتق می‌کند. فقط متادیتای نمایشی؛ هیچ
    Entitlement/نسخه/اشتراکی لمس نمی‌شود و رفتارِ فعلیِ ماتریسِ عمومی (قابلیت‌هایِ پیاده‌شده در دسترس، «planned» پنهان) حفظ می‌شود."""
    Feature = apps.get_model("subscriptions", "PricingFeature")
    for f in Feature.objects.all():
        ready = f.availability != "planned"
        f.technical_status = "ready" if ready else "planned"
        f.commercial_status = "available" if ready else "planned"
        f.value_type = "integer_limit" if (f.entitlement_id and f.entitlement.entitlement_type == "integer_limit") else "boolean"
        f.save(update_fields=["technical_status", "commercial_status", "value_type"])


